// TH15 Stage 7 (Extra) 道中 w10：第三组 GirlD04（源 I0=14，单只，无 ENM_CNT 门控）。
// 源：st07.ecl.txt:1287-1290 entry；GirlD04 820-844；GirlD04_at 861-897。
// 卡帧 0 = 源 MainSub07:1287 的这次 enmCreate；120 帧开场缓冲后创建本敌。

const TIME_LIMIT: int = 2824;      // 120 开场 + 2700 本波窗口估计 + 4 启动余量
const OPENING_BUFFER: int = 120;

const TH15_OVAL: int = 672;        // etSprite(0,20,3)：TH15 type20=OVAL，基础半径7，色3有效
const BULLET_COLOR: int = 3;

const START_WAYS: int = 14;        // 源 $I0=14（GirlD04_at 起手）
const MAX_WAYS: int = 32;          // 源 $I0<32 才 +1
const BASE_SPEED: fx = 2fx;        // etSpeed(0,2.0,0.2)：layers=1 只取首速 2.0
const TURN_STEP: angle = 222.5deg; // 源 %A = %A - 3.883222f（rad 222.5°）

// 源 EX 记录（etEx 追加游标 0/1 + etExSet 槽 2）：
//   slot0 ANIM a=1（出生表现；按已批准口径省略，但保留 position -= 4*velocity）
//   slot1 OFFSCREEN a=360 b=0
//   slot2 ANGLE_ACCEL a=120 r=0.01 s=±0.017453292（rad，每帧 ±1°）
// ANIM 退位移与 etDist(24) 合成后每颗弹沿自身角度净出距 24 - 4*2 = 16。
xformdef GIRL_ORBIT(turn_dir: angle) {
    offscreen_keep(360);
    set_ang_vel(turn_dir);
    set_accel(0.01fx);
    wait(120);
    set_ang_vel(0deg);
    set_accel(0fx);
}

async sub girl_at() {
    wait(60);                                  // 861-864: wait(60)
    sh_reset(0);                               // 865 etNew(0)
    sh_sprite(0, TH15_OVAL, BULLET_COLOR);     // 867 etSprite(0,20,3)
    sh_ring(0, 1);                             // 866 etAim(0,3)：固定方向整周环
    sh_aim(0, 0);
    sh_speed(0, BASE_SPEED, 0fx);              // 870 etSpeed(0,2.0,0.2)，单层取 2.0
    sh_dist(0, 16fx);                          // 873 etDist(24) + 出生 ANIM(-4*2)
    var base: angle = rand(65536) as angle;    // 874 %RANDRAD：整周基点只抽一次
    var b: int = -1;                           // 875 $B=-1
    var c: int = 1000;                         // 876 $C=1000
    var ways: int = START_WAYS;                // 源敌 I0：只在本 async 读写
    while c > 0 {                              // 894-895 if ($C--) goto 468
        c = c - 1;
        b = b + 1;                             // 879 $B=$B+1
        sh_count(0, ways, 1);                  // 880 etCount(0,$I0,1)
        sh_angle(0, base, 0deg);               // 882 etAngle(0,%A,0)
        sh_xform(0, GIRL_ORBIT(1deg));         // 881 ANGLE_ACCEL s=+1°
        sh_fire(0);                            // 883 etOn(0)
        base = base - TURN_STEP;               // 884 %A-=3.883222
        wait(20);                              // 885
        sh_count(0, ways, 1);                  // 880 etCount(0,$I0,1)
        sh_angle(0, base, 0deg);               // 887 etAngle(0,%A,0)
        sh_xform(0, GIRL_ORBIT(-1deg));        // 886 ANGLE_ACCEL s=-1°
        sh_fire(0);                            // 888 etOn(0)
        base = base - TURN_STEP;               // 889 %A-=3.883222
        wait(20);                              // 890
        if b % 7 == 6 && ways < MAX_WAYS {     // 891-893 每 7 次且未到上限才 +1
            ways = ways + 1;
        }
    }
}

async sub girl_body() {
    set_invuln(65535);                         // 无击破存活路径
    set_hurtbox(16fx);                         // 826 setHurtbox(32,32) -> 第一值*0.5
    set_hitbox(12fx);                          // 827 setHitbox(24,24) -> 第一值*0.5
    move_vel(0, 90deg, 4.7fx, EASE_LINEAR);    // 829 moveVel(rad(90),4.7)：立即向下
    move_speed(60, 0fx, EASE_QUAD_IN);         // 830 moveSpeedTime(60,mode1,0.0)：t² 减到 0
    spawn girl_at();                           // 831 @GirlD04_at() async
    wait(1200);                                // 832
    move_vel(0, -90deg, 0fx, EASE_LINEAR);     // 833 moveVel(rad(-90),0)：改向上、停住
    move_speed(60, 0.5fx, EASE_QUAD_IN);       // 834 moveSpeedTime(60,mode1,0.5)
    wait(600);                                 // 835
    move_speed(80, 1fx, EASE_QUAD_IN);         // 836 moveSpeedTime(80,mode1,1.0)
    wait(60);                                  // 837
    loop { wait(1000); }                       // 839-842 GirlD04_476/496
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // 1290 enmCreate("GirlD04",0,-48,10000,1000,0)：目标 spawn 参序 hp/drop/score/sprite
    _ = spawn_enemy(0fx, -48fx, 10000, 0, 1000, 0, girl_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
